package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveEntry_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertTrue("Should return true for same instance", entry.equals(entry));
    }

    @Test
    public void testEquals_NullObject() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertFalse("Should return false when comparing with null", entry.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        String other = "test.txt";
        assertFalse("Should return false when comparing with different class", entry.equals(other));
    }

    @Test
    public void testEquals_SameName() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        assertTrue("Should return true for same name", entry1.equals(entry2));
    }

    @Test
    public void testEquals_DifferentName() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("other.txt");
        assertFalse("Should return false for different names", entry1.equals(entry2));
    }

    @Test
    public void testEquals_BothNamesNull() {
        // Using reflection or a way to set name to null if possible. 
        // Given the constructor, we might need to rely on the fact that name could be null 
        // if the class allows it via other means or if we simulate it.
        // Since the code specifically checks `if (name == null)`, we must trigger this branch.

        ZipArchiveEntry entry1 = new ZipArchiveEntry(null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry(null);

        assertTrue("Should return true when both names are null", entry1.equals(entry2));
    }

    @Test
    public void testEquals_OneNameNullOtherNameNotNull() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry(null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");

        assertFalse("Should return false when first name is null and second is not", entry1.equals(entry2));
    }

    @Test
    public void testEquals_OneNameNotNullOtherNameNull() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry(null);

        assertFalse("Should return false when first name is not null and second is", entry1.equals(entry2));
    }
}
